    private MicEnhancement() {
    }

    public static float[] getFilterForSampleRate(int sampleRate) {
        return sampleRate >= 40000 ? IR_48K : sampleRate >= 28000 ? IR_32K : sampleRate >= 12000 ? IR_16K : IR_8K;
    }

    public static boolean isEnabled() {
        return enabled;
    }

    public static void setEnabled(boolean value) {
        enabled = value;
        if (!value) {
            resetState();
        }
    }

    public static void resetState() {
        synchronized (lock) {
            Arrays.fill(historyL, 0.0f);
            Arrays.fill(historyR, 0.0f);
        }
    }

    public static void process(byte[] bArr, int offset, int length, int sampleRate, int channels) {
        int numSamples;
        if (!enabled || bArr == null || length <= 0) {
            return;
        }
        if ((channels == 1 || channels == 2) && (numSamples = length / (channels * 2)) > 0 && numSamples <= MAX_FRAME_SAMPLES) {
            float[] filter = getFilterForSampleRate(sampleRate);
            int filterLen = filter.length;
            int filterLenAligned = filterLen & (-4);

            synchronized (lock) {
                try {
                    if (channels == 1) {
                        System.arraycopy(historyL, 0, workBufferL, 0, filterLen);
                        int readIdx = offset;
                        for (int i = 0; i < numSamples; i++) {
                            workBufferL[filterLen + i] = (short) ((bArr[readIdx] & 255) | (bArr[readIdx + 1] << 8));
                            readIdx += 2;
                        }
                        int writeIdx = offset;
                        for (int i = 0; i < numSamples; i++) {
                            int base = filterLen + i;
                            float sum0 = 0.0f;
                            float sum1 = 0.0f;
                            float sum2 = 0.0f;
                            float sum3 = 0.0f;
                            int j = 0;
                            while (j < filterLenAligned) {
                                float[] buf = workBufferL;
                                sum0 += buf[base - j] * filter[j];
                                int j1 = j + 1;
                                sum1 += buf[base - j1] * filter[j1];
                                int j2 = j + 2;
                                sum2 += buf[base - j2] * filter[j2];
                                int j3 = j + 3;
                                sum3 += buf[base - j3] * filter[j3];
                                j += 4;
                            }
                            float total = sum0 + sum1 + sum2 + sum3;
                            while (j < filterLen) {
                                total += workBufferL[base - j] * filter[j];
                                j++;
                            }
                            short sample = VoiceChanger.clampToShort(total);
                            bArr[writeIdx] = (byte) (sample & 255);
                            bArr[writeIdx + 1] = (byte) ((sample >> 8) & 255);
                            writeIdx += 2;
                        }
                        System.arraycopy(workBufferL, numSamples, historyL, 0, filterLen);
                    } else {
                        System.arraycopy(historyL, 0, workBufferL, 0, filterLen);
                        System.arraycopy(historyR, 0, workBufferR, 0, filterLen);
                        int readIdx = offset;
                        for (int i = 0; i < numSamples; i++) {
                            int base = filterLen + i;
                            workBufferL[base] = (short) ((bArr[readIdx] & 255) | (bArr[readIdx + 1] << 8));
                            workBufferR[base] = (short) ((bArr[readIdx + 2] & 255) | (bArr[readIdx + 3] << 8));
                            readIdx += 4;
                        }
                        int writeIdx = offset;
                        for (int i = 0; i < numSamples; i++) {
                            int base = filterLen + i;
                            float sumL0 = 0.0f;
                            float sumL1 = 0.0f;
                            float sumL2 = 0.0f;
                            float sumL3 = 0.0f;
                            float sumR0 = 0.0f;
                            float sumR1 = 0.0f;
                            float sumR2 = 0.0f;
                            float sumR3 = 0.0f;
                            int j = 0;
                            while (j < filterLenAligned) {
                                float f0 = filter[j];
                                int j1 = j + 1;
                                float f1 = filter[j1];
                                int j2 = j + 2;
                                float f2 = filter[j2];
                                int j3 = j + 3;
                                float f3 = filter[j3];

                                float[] bufL = workBufferL;
                                sumL0 += bufL[base - j] * f0;
                                sumL1 += bufL[base - j1] * f1;
                                sumL2 += bufL[base - j2] * f2;
                                sumL3 += bufL[base - j3] * f3;

                                float[] bufR = workBufferR;
                                sumR0 += bufR[base - j] * f0;
                                sumR1 += bufR[base - j1] * f1;
                                sumR2 += bufR[base - j2] * f2;
                                sumR3 += bufR[base - j3] * f3;

                                j += 4;
                            }
                            float totalL = sumL0 + sumL1 + sumL2 + sumL3;
                            float totalR = sumR0 + sumR1 + sumR2 + sumR3;
                            while (j < filterLen) {
                                float f = filter[j];
                                int idx = base - j;
                                totalL += workBufferL[idx] * f;
                                totalR += workBufferR[idx] * f;
                                j++;
                            }
                            short sampleL = VoiceChanger.clampToShort(totalL);
                            short sampleR = VoiceChanger.clampToShort(totalR);
                            bArr[writeIdx] = (byte) (sampleL & 255);
                            bArr[writeIdx + 1] = (byte) ((sampleL >> 8) & 255);
                            bArr[writeIdx + 2] = (byte) (sampleR & 255);
                            bArr[writeIdx + 3] = (byte) ((sampleR >> 8) & 255);
                            writeIdx += 4;
                        }
                        System.arraycopy(workBufferL, numSamples, historyL, 0, filterLen);
                        System.arraycopy(workBufferR, numSamples, historyR, 0, filterLen);
                    }
                } catch (Throwable th) {
                    throw th;
                }
            }
        }
    }
